/bin/bash -lc "python - <<'PY'
import os, requests, json
url=os.environ['GALAXY_URL'].rstrip('/')
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
headers={'x-api-key':key}
tool='toolshed.g2.bx.psu.edu/repos/iuc/bcftools_norm/bcftools_norm/1.24+galaxy0'
data=requests.get(f'{url}/api/tools/{tool}/build', headers=headers, params={'history_id':'bbd44e69cb8906b5cafcf6af0114ac74'}).json()
# recursively find fasta_ref select options
matches=[]
def walk(x,path=''):
    if isinstance(x,dict):
        if x.get('name')=='fasta_ref' or x.get('label')=='Reference genome':
            opts=x.get('options') or []
            for opt in opts:
                text=json.dumps(opt)
                if any(s.lower() in text.lower() for s in ['hg18','hg19','hg38','chm13','t2t','grch37','grch38','human']):
                    matches.append(opt)
        for k,v in x.items(): walk(v,path+'/'+k)
    elif isinstance(x,list):
        for i,v in enumerate(x): walk(v,path+f'/{i}')
walk(data)
print('match_count', len(matches))
for opt in matches[:200]:
    print(opt)
PY"

