/bin/bash -lc "python - <<'PY'
import os, requests, json
url=os.environ['GALAXY_URL'].rstrip('/')
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
headers={'x-api-key':key}
tool='toolshed.g2.bx.psu.edu/repos/iuc/extract_genomic_dna/Extract genomic DNA 1/3.0.3+galaxy3'
data=requests.get(f'{url}/api/tools/{tool}/build', headers=headers, params={'history_id':'bbd44e69cb8906b5cafcf6af0114ac74'}).json()
opts=[]
def walk(x):
    if isinstance(x,dict):
        if x.get('name')=='reference_genome':
            opts.extend(x.get('options') or [])
        for v in x.values(): walk(v)
    elif isinstance(x,list):
        for v in x: walk(v)
walk(data)
for needle in ['hg18','hg19','hg38','hs1','chm13','GCA_009914755','T2T']:
    m=[o for o in opts if needle.lower() in json.dumps(o).lower()]
    print(needle, len(m), m[:10])
PY"

